select t.transaction_id, t.customer_id, t.product_id, t.transaction_date, t.process_date, t.transaction_type, t.transaction_category, t.amount, t.currency, t.amount_usd, t.channel, t.merchant_name, t.merchant_category, t.transaction_country, t.transaction_status, c.country as customer_country, p.product_status, t._dataset_version, t._source_file, t._source_sha256, t._ingested_at, t._pipeline_version from {{ source('silver','transactions') }} t join {{ source('silver','products') }} p on t.product_id=p.product_id and t.customer_id=p.customer_id join {{ source('silver','customers') }} c on t.customer_id=c.customer_id
